// UUIDv7 (RFC 9562): 48-bit Unix ms timestamp + random. Time-ordered, so B-tree
// indexes stay compact; generated by the app so offline devices can create ids (ADR-02).
// Works in Node (main/server) and the browser (renderer) via Web Crypto.

let lastMs = -1;
let seq = 0;

export function uuidv7(now: number = Date.now()): string {
  const bytes = new Uint8Array(16);
  globalThis.crypto.getRandomValues(bytes);

  // Monotonic within the same millisecond: a 12-bit counter in rand_a.
  if (now === lastMs) {
    seq = (seq + 1) & 0x0fff;
  } else {
    lastMs = now;
    seq = (((bytes[6] ?? 0) << 8) | (bytes[7] ?? 0)) & 0x07ff;
  }

  const ms = BigInt(now);
  for (let i = 0; i < 6; i++) bytes[i] = Number((ms >> BigInt(8 * (5 - i))) & 0xffn);
  bytes[6] = 0x70 | ((seq >> 8) & 0x0f); // version 7
  bytes[7] = seq & 0xff;
  bytes[8] = 0x80 | ((bytes[8] ?? 0) & 0x3f); // RFC 4122 variant

  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

export const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
